# Convert text in adc format generated by lm to midi and audio

bpm_types = [40,60,90,120,144]

ts_music_name = {
    '2/4': 'gen_melody_ts24',
    '3/4': 'gen_melody_ts34',
    '4/4': 'gen_melody_ts44',
    '6/8': 'gen_melody_ts68',
    '3/8': 'gen_melody_ts38',
}

def parse_l_parameter(header):
    """
    Parse the L parameter (base note duration) from the header information and return the fractional value of the note duration (e.g., L:1/8 → 1/8)

    Parameters:
        header (str): String of the header information of ABC music

    Returns:
        float: Numeric value of the base note duration (e.g., 1/8 = 0.125), returns 0.125 (L:1/8) by default
    """
    # Regular expression to match L parameter: fraction (e.g., 1/8) or integer (e.g., 1) after L:
    l_pattern = re.compile(r'L:(\d+/\d+|\d+)', re.IGNORECASE)
    match = l_pattern.search(header)
    if not match:
        return 1 / 8  # Default base note duration is eighth note

    l_value = match.group(1)
    if '/' in l_value:
        numerator, denominator = map(int, l_value.split('/'))
        return numerator / denominator
    else:
        return int(l_value)  # e.g., L:1 → 1 beat


def parse_note_duration(note_str, base_duration):
    """
    Parse the actual duration of a single note and return the duration value (in beats)

    Parameters:
        note_str (str): String of a single note (e.g., e/f/g, cB, g2, d3/4)
        base_duration (float): Base note duration (value parsed from the L parameter)

    Returns:
        float: Actual duration of the note (in beats)
    """
    # Regular expression match: pitch part (letters + modifiers) + duration part (fraction/integer, optional)
    # Pitch matching rules: includes a-g/A-G, accidentals ^/_, octave '/,, , tie /
    note_pattern = re.compile(r'([a-gA-G^/_/,]+)(\d+/\d+|\d+)?')
    match = note_pattern.match(note_str)

    if not match:
        return base_duration  # Return base duration if parsing fails

    pitch_part, duration_part = match.groups()

    # No duration marker → base duration
    if not duration_part:
        return base_duration

    # Parse duration multiplier
    if '/' in duration_part:
        num, den = map(int, duration_part.split('/'))
        duration_multiplier = num / den
    else:
        duration_multiplier = int(duration_part)

    # Actual duration = base duration × multiplier
    return base_duration * duration_multiplier


def check_long_duration_notes(abc_music_list, max_threshold=32):
    """
    Check if there are notes with duration exceeding the threshold in the flattened bar list

    Parameters:
        abc_music_list (list): Flattened bar list (return value of flatten_abc_music)
        max_threshold (int/float): Maximum threshold for note duration (32 beats by default)

    Returns:
        list: List of over-threshold information, each element is a dictionary:
              {'bar_num': bar number, 'note': note string, 'duration': actual duration, 'threshold': threshold value}
    """
    if len(abc_music_list) == 0:
        return []

    # Step 1: Parse base note duration
    header = abc_music_list[0]
    base_duration = parse_l_parameter(header)

    # Step 2: Traverse each bar and check note durations
    over_limit_notes = []

    for bar_num, bar_content in enumerate(abc_music_list):
        if bar_num == 0:
            continue  # Skip header information

        # Split notes in the bar (split by spaces, handle ties/combined notes)
        # First split note groups separated by spaces, then split ties/ (e.g., e/f/g split into e, f, g)
        note_groups = bar_content.split()
        for note_group in note_groups:
            # Split ties (e.g., e/f/g → [e, f, g], cB is a combined note and not split)
            if '/' in note_group and any(c in note_group for c in 'abcdefgABCDEFG'):
                sub_notes = note_group.split('/')
            else:
                sub_notes = [note_group]

            # Check duration of each sub-note
            for sub_note in sub_notes:
                if not sub_note.strip():
                    continue
                note_duration = parse_note_duration(sub_note, base_duration)
                if note_duration > max_threshold:
                    over_limit_notes.append({
                        'bar_num': bar_num,
                        'note': sub_note,
                        'duration': round(note_duration, 2),
                        'threshold': max_threshold
                    })

    return over_limit_notes



def insert_substring(original_str: str, sub_str: str, pos: int) -> str:
    """
    Insert a substring at the specified position of the original string (does not modify the original string, returns a new string)

    Parameters:
        original_str: Original string (the main string to be inserted into)
        sub_str: Substring to be inserted
        pos: Insertion position (index starts from 0)

    Boundary handling:
        1. pos ≤ 0 → Insert at the beginning of the string
        2. pos ≥ len(original_str) → Insert at the end of the string
        3. If the original string is empty → Directly return the inserted substring

    Returns:
        new_str: New string after insertion
    """
    # Handle empty original string
    if not original_str:
        return sub_str

    # Handle out-of-range insertion positions (limit between 0 ~ length of string)
    insert_pos = max(0, min(pos, len(original_str)))

    # Core logic: slice concatenation to implement insertion
    new_str = original_str[:insert_pos] + sub_str + original_str[insert_pos:]

    return new_str

# Set different tempos using miditoolkit


def run_midi_to_audio(midi_file_path, save_dir, m_name, sound_font = "compound.sf2"):
    audio_file = os.path.join(save_dir, m_name)  + ".wav"
    try:
        result = subprocess.run(
            [
                "fluidsynth",
                "-F",
                audio_file,
                sound_font,
                midi_file_path,
            ],
            check = True,
            capture_output = True,
            encoding = 'utf-8'
        )
    except FileNotFoundError as e:
        # Catch the error of non-existent files (e.g., xml2abc.py, demo.xml do not exist, or the Python interpreter cannot find them)
        print(f"Failed to convert midi to audio: specified file not found - {e}")
    except Exception as e:
        # Catch other unknown errors
        print(f"Failed to convert midi to audio: unknown error - {e}")



def save_xml_file_from_abc_text(abc_text, save_xml_file):

    print('Saving abc file')

    try:
        # Parse the ABC string into a music21 Stream object (core step)
        # format='abc' specifies the parsing format as ABC
        # music_stream_abc = converter.subConverters.ConverterABC.parseData(strData=abc_str)
        music_stream = converter.parse(value=abc_text, format='abc')

        # Save the music object as an XML file
        # 'xml' specifies the output format, fp specifies the file path
        music_stream.write('xml', fp=save_xml_file)

        print(f"✅ XML file saved successfully to: {save_xml_file}")
        return music_stream  # Return parsed music21 object for subsequent processing

    except Exception as e:
        print(f"❌ Conversion failed: {str(e)}")
        return None


def save_dict_to_json(data, json_save_file_path):
    """
    Save a dictionary as a JSON file
    :param data: Dictionary to be saved (save_dir_content)
    :param json_save_file_path: Save path of the JSON file
    :return: Boolean value, True for successful saving, False for failure
    """
    # 1. Validate input: ensure data is a dictionary type
    if not isinstance(data, dict):
        print(f"Error: Input data is not a dictionary type, actual type is {type(data)}")
        return False

    try:
        # 2. Extract the file directory and ensure it exists (create if the directory does not exist)
        # For example, for the path "static/item_content/rhythm44.json", extract "static/item_content/"
        dir_path = os.path.dirname(json_save_file_path)
        if dir_path and not os.path.exists(dir_path):
            os.makedirs(dir_path, exist_ok=True)  # exist_ok=True avoids error if directory already exists

        # 3. Write to JSON file
        # ensure_ascii=False: support normal display of non-ASCII characters such as Chinese
        # indent=4: format JSON for easy reading and debugging
        with open(json_save_file_path, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=4)

        print(f"Success: Dictionary saved to {json_save_file_path}")
        return True

    except PermissionError:
        print(f"Error: No permission to write to file {json_save_file_path}")
        return False
    except IOError as e:
        print(f"Error: File IO exception - {str(e)}")
        return False
    except Exception as e:
        print(f"Error: Failed to save JSON - {str(e)}")
        return False


def abc_to_midi(abc_str, output_path='abc_music_to_midi.mid', remove_bar=True):
    """
    Convert ABC format music string to MIDI file
    :param remove_bar: Remove bar lines in the music body
    :param abc_str: ABC music string
    :param output_path: Path/name of the output MIDI file
    """
    try:

        # Remove bar lines in the music body
        if remove_bar:
            remove_bar_str = remove_bar_in_lm_abc(abc_str)
        else:
            remove_bar_str = abc_str

        music_stream = converter.parse(value=remove_bar_str, format='abc')

        # Test
        # music_stream.show()

        # Save the music object as a MIDI file
        music_stream.write('midi', fp=output_path)

        print(f"✅ MIDI file saved successfully to: {output_path}")
        return music_stream  # Return parsed music21 object for subsequent processing

    except Exception as e:
        print(f"❌ Conversion failed: {str(e)}")
        print("ERR! Error executing function abc_to_midi! ABC to be converted: ", abc_str)
        return None


# Remove bar lines in ABC music string
def remove_bar_in_lm_abc(abc_full_str:str):

    abc_full_list = abc_full_str.split("\n")
    # Note! There are key changes and time signature changes in the body: |\n[M:2/4] z2 z B, ||[K:Db][M:4/4] BB/A/- A<F ED/E/- EB, |

    abc_body = []
    for abc in abc_full_list:  # Blacklist writing method
        if "| " in abc or " | " in abc or "|]" in abc: # Remove bar lines in the body
            # To remove extra spaces and avoid bugs, handle carefully: first remove those with spaces, then those without
            abc = abc.replace(" | ", " ")
            abc = abc.replace(" |", " ")
            abc = abc.replace("|", " ")
            abc = abc.replace(" ||", " ")
            abc = abc.replace("||", " ")
            abc = abc.replace("|: ", " ")
            abc = abc.replace("|:", " ")
            abc = abc.replace(" :|", " ")
            abc = abc.replace(":|", " ")
            abc = abc.replace(":|1", " ")
            abc = abc.replace(":|2", " ")
            abc = abc.replace(":|3", " ")
            abc = abc.replace(" ::", " ")
            abc = abc.replace("::", " ")
            abc = abc.replace("|]", " ")
            abc = abc.replace(" ]", " ")
            abc = abc.replace("\n", " ")

            # Remove time signature changes in the music body, e.g., [M:2/4]
            pattern_m = r'\[M:\d+/\d+\]'
            tem_str = re.sub(pattern_m, '', abc)

            abc_body.append(tem_str.strip())
            abc_body.append(' ')
        else:
            abc_body.append(abc.strip()) # Keep other headers
            abc_body.append('\n') # Keep other headers, add '\n' after header fields

    abc_body_str = "".join(abc_body)
    abc_body_str += "|]"
    return abc_body_str


def batch_gen_melody_file_and_item(
        file_path="lm-gen-melody/generated_texts_ts_44.json",
        select_number:int=5,
        seed:int = 400,
        save_path="static/music_theory_examination/lm_gen_melody"
):

    all_data = []  # Initialize empty list to store all dictionaries

    save_dir_content = {}  # Save time signature type and file information

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            # Read file line by line
            for line_num, line in enumerate(f, 1):
                # Remove whitespace characters (newlines, spaces, etc.) from both ends of the line
                line = line.strip()
                if not line:  # Skip empty lines
                    continue
                # Parse single-line JSON into dictionary and add to list
                try:
                    dict_data = json.loads(line)
                    all_data.append(dict_data)
                except json.JSONDecodeError:
                    print(f"Warning: Line {line_num} has incorrect format, skipped")
    except FileNotFoundError:
        print(f"Error: File {file_path} not found")


    random.seed(seed)
    all_data_sample = random.sample(all_data, select_number)

    for abc_data in all_data_sample:
        abc_music = abc_data['text']

        # Check if the ABC representation generated by AI exists
        have_err = False

        for bpm_i in range(len(bpm_types)): # Insert five tempos
            print("List of all bpm values: ", bpm_types)
            print("Inserting a bpm value: ", bpm_types[bpm_i])  # Note: bpm_i may be assigned elsewhere
            bpm_name = f"Q:1/4={str(bpm_types[bpm_i])}\n"
            print("Insert bpm into header: ", bpm_name)
            abc_music_with_bpm = insert_substring(abc_music, bpm_name, 10)
            ts = abc_music[12:15]
            music_name = ts_music_name[ts]
            abc_split = flatten_abc_music(abc_music_with_bpm)  # Flatten the music to display all repeated sections
            for abc in abc_split:
                # Error check: empty bars
                if abc is None:
                    print("ERR! ")
                    have_err = True
                    break
                # Error check: excessively long note durations
                over_limit_notes = check_long_duration_notes(abc_split, max_threshold=64)
                # print(over_limit_notes)
                if over_limit_notes:
                    have_err = True

            if have_err:
                break

            # This information is saved in JSON for question generation
            if len(abc_split) >= 9:  # Total bars greater than 8 (greater than 5 because of the header)

                ms_timestamp = str(int(time.time() * 1000))
                music_name += "_gentime_" + ms_timestamp + '_bpm' + str(bpm_types[bpm_i])
                music_midi_name = music_name  + '.mid'

                midi_path = os.path.join(save_path, music_midi_name)

                try:
                    # Remove bar lines to improve robustness and reduce issues caused by incorrect bar durations in generated music
                    music21_object = abc_to_midi(
                        abc_music_with_bpm, output_path=midi_path
                    )

                    if music21_object:
                        run_midi_to_audio(
                            midi_file_path=midi_path,
                            save_dir=save_path,
                            m_name=music_name,
                            sound_font="sf2_files/compound.sf2"
                        )  # midi_file_path, save_dir, m_name, sound_font = "compound.sf2"

                        save_dir_content[music_name] = {
                            "time signature": ts,
                            "bpm": str(bpm_types[bpm_i]),
                            "bar": abc_split,
                            "bar_number": len(abc_split)-1,
                            "wav_path": os.path.join(save_path, music_name) + '.wav'
                        }
                    else:
                        print("No midi object.")
                except Exception as e:
                    print(e)
            else:
                continue

            print("Processing completed, bpm_i: ", bpm_i)

    return save_dir_content


def flatten_abc_music(abc_music):
    """
    Parse the ABC-encoded music string, expand repeated bars, and return the flattened bar list

    Parameters:
        abc_music (str): Complete ABC-encoded music string

    Returns:
        list: Flattened bar list, the first element is the music header information (X/L/M/K), followed by the content of each bar
    """
    # Define bar delimiters (sorted by longest match first to avoid splitting compound symbols)
    delimiters = ['::', '|:', ':|', '|]', '||', '[|', '|']

    # ===================== Step 1: Split header information and music body =====================
    lines = abc_music.split('\n')
    header_lines = []  # Store header information (X:/L:/M:/K:)
    body_parts = []  # Store music body (note section)

    for line in lines:
        stripped_line = line.strip()
        # Identify header lines (starting with X/L/M/K)
        if stripped_line.startswith(('X:', 'L:', 'Q:', 'M:', 'K:')):
            header_lines.append(line)
        # Identify music body lines (non-empty lines that are not headers)
        elif stripped_line:
            body_parts.append(stripped_line)

    # Concatenate header and body (body is concatenated into a single line to avoid line breaks interfering with splitting)
    header = '\n'.join(header_lines)
    body = ' '.join(body_parts).strip()  # Concatenate body and remove leading/trailing spaces

    # ===================== Step 2: Split body into sequence of [delimiter + bar content] =====================
    tokens = []  # Store tuples (delimiter, bar content)
    current_pos = 0
    body_len = len(body)

    while current_pos < body_len:
        # Skip irrelevant spaces
        while current_pos < body_len and body[current_pos].isspace():
            current_pos += 1
        if current_pos >= body_len:
            break

        # Step 2.1: Match delimiters with longest match first
        matched_sep = None
        for sep in delimiters:
            sep_len = len(sep)
            # Check if current position matches the delimiter
            if current_pos + sep_len <= body_len and body[current_pos:current_pos + sep_len] == sep:
                matched_sep = sep
                current_pos += sep_len
                break

        # Step 2.2: Extract bar content after the delimiter (until the next delimiter)
        content_start = current_pos
        # Traverse until the next delimiter is encountered
        while current_pos < body_len and not any(body.startswith(sep, current_pos) for sep in delimiters):
            current_pos += 1
        # Extract and clean bar content (remove leading and trailing spaces)
        bar_content = body[content_start:current_pos].strip()

        # Record delimiter and bar content
        tokens.append((matched_sep, bar_content))

    # ===================== Step 3: Handle repetition logic and expand bars =====================
    flattened_bars = []
    # Add header information (first element)
    if header:
        flattened_bars.append(header)

    repeat_start = None  # Record start index of repeated segment (position in flattened_bars)

    for sep, content in tokens:
        # Skip empty bar content (avoid invalid elements)
        if not content and len(flattened_bars) > 0:
            continue

        # Handle repetition logic for different delimiters
        if sep == '|:':
            # Mark start of repeated segment: record current list length (next bar is start of repetition)
            repeat_start = len(flattened_bars)
            flattened_bars.append(content)

        elif sep == ':|':
            # Mark end of repeated segment: copy bars from repeat_start to current position
            if repeat_start is not None and repeat_start < len(flattened_bars):
                # Extract repeated segment and add to list
                repeated_segment = flattened_bars[repeat_start:]
                flattened_bars.extend(repeated_segment)
                repeat_start = None  # Reset repeat start marker
            flattened_bars.append(content)

        elif sep == '::':
            # Compound symbol: both end of repetition (:|) and start of new repetition (|:)
            # Step 1: Handle end of repetition
            if repeat_start is not None and repeat_start < len(flattened_bars):
                repeated_segment = flattened_bars[repeat_start:]
                flattened_bars.extend(repeated_segment)
            # Step 2: Mark start of new repeated segment
            repeat_start = len(flattened_bars)
            flattened_bars.append(content)

        else:
            # Normal delimiters (|/|]/||/[|): add bar content directly
            flattened_bars.append(content)

    return flattened_bars



